#include <string>

using namespace std;

class Solution {
public:
    int reverseDegree(string s) {
        int ans = 0;
        for (int i = 0; i < (int)s.length(); ++i) {
            int revVal = 'z' - s[i] + 1;
            ans += (i + 1) * revVal;
        }
        return ans;
    }
};

class Solution {
    public int reverseDegree(String s) {
        int ans = 0;
        for (int i = 0; i < s.length(); i++) {
            int revVal = 'z' - s.charAt(i) + 1;
            ans += (i + 1) * revVal;
        }
        return ans;
    }
}

var reverseDegree = function(s) {
    let ans = 0;
    for (let i = 0; i < s.length; i++) {
        const revVal = 122 - s.charCodeAt(i) + 1;
        ans += (i + 1) * revVal;
    }
    return ans;
};
